/* Browser-local routine support. Records are self-reported, never verified doses. */
(function (root) {
  'use strict';
  const dateKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const at = (day, time) => new Date(`${day}T${time}:00`).getTime();
  const occurrence = (meal, day) => `${meal.id}|${day}`;
  function mealsFor(data, day) {
    const weekday = new Date(`${day}T12:00:00`).getDay();
    return data.meals.map(m => ({...m, version: [...m.versions].reverse().find(v => v.from <= day)})).filter(m => m.version && !m.version.deleted && m.version.days.includes(weekday));
  }
  function status(record, meal, day, now) {
    if (record?.helpAt && !record.ackAt) return 'Help requested';
    if (record?.completedAt) return `${record.source === 'parent' ? 'Parent' : 'Child'}-reported completion`;
    return now < at(day, meal.version.time) ? 'Upcoming' : 'Awaiting check-in';
  }
  function summary(data, now = new Date()) {
    return Array.from({length:7}, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth(), now.getDate()-6+i, 12), day = dateKey(d);
      const rows = mealsFor(data, day).map(m => ({m, r:data.records[occurrence(m, day)] || {}}));
      return {day, scheduled:rows.length, recorded:rows.filter(x=>x.r.completedAt).length,
        pending:rows.filter(x=>!x.r.completedAt && at(day,x.m.version.time)>now.getTime()).length,
        noRecord:rows.filter(x=>!x.r.completedAt && at(day,x.m.version.time)<=now.getTime()).length,
        help:rows.filter(x=>x.r.helpAt).length, snoozes:rows.reduce((n,x)=>n+(x.r.snoozes||0),0)};
    });
  }
  function attemptFailure(data, now) { data.attempts++; if (data.attempts >= 5) {data.lockUntil = now + 60000; data.attempts = 0;} }
  function actionRecord(r, action, now, source) {
    if (action === 'record' && !r.completedAt) return {...r, completedAt:now, source, snoozeUntil:null};
    if (action === 'snooze' && !r.completedAt) return {...r,snoozeUntil:now+300000,snoozes:(r.snoozes||0)+1};
    if (action === 'help' && !r.completedAt && !r.helpAt) return {...r,helpAt:now,ackAt:null};
    if (action === 'ack' && r.helpAt && !r.ackAt) return {...r,ackAt:now};
    return r;
  }
  const core = {dateKey, at, occurrence, mealsFor, status, summary, attemptFailure, actionRecord};
  if (typeof module !== 'undefined' && module.exports) module.exports = core;
  if (!root.document) return;
  const $ = s => document.querySelector(s), esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const key='diabuddy-routine-v1', blank=()=>({meals:[],records:{},pin:null,attempts:0,lockUntil:0});
  let data; try { data={...blank(),...JSON.parse(localStorage.getItem(key)||'{}')}; } catch {data=blank();}
  let unlocked=false, demo=false, demoData=blank(), reminderNotice='', shown=new Set();
  const current=()=>demo?demoData:data, persist=()=>{if(!demo)localStorage.setItem(key,JSON.stringify(data));};
  const id=()=>crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
  const fmt=t=>t?new Date(t).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'—';
  const timeLabel=t=>new Date(`2000-01-01T${t}:00`).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
  const recordFor=(m,day)=>current().records[occurrence(m,day)]||{};
  const put=(m,day,patch)=>{const k=occurrence(m,day); current().records[k]={...current().records[k],...patch};persist();};
  function dialog(html) { const el=$('#modal'); $('#modal-content').innerHTML=html; if(!el.open)el.showModal(); }
  function close(){if($('#modal').open)$('#modal').close();}
  async function digest(pin,salt) {const bytes=new TextEncoder().encode(salt+pin);return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');}
  function pinDialog(error='') {
    const setting=!data.pin, locked=Date.now()<data.lockUntil;
    dialog(`<div class="eyebrow">PARENT PORTAL · BASIC BETA BARRIER</div><h2>${setting?'Create a parent PIN':'Enter parent PIN'}</h2><p>${setting?'Choose four digits and enter them twice.':'Enter your four-digit PIN to continue.'} This is a basic access barrier, not medical-account security.</p><form id="pin-form" class="routine-form"><label>Four-digit PIN<input name="pin" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{4}" maxlength="4" required></label>${setting?'<label>Confirm PIN<input name="confirm" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{4}" maxlength="4" required></label>':''}<p class="routine-error" role="alert">${esc(locked?'Too many attempts. Try again in '+Math.ceil((data.lockUntil-Date.now())/1000)+' seconds.':error)}</p><div class="routine-actions"><button type="button" class="secondary" id="pin-cancel">Cancel</button><button class="primary" ${locked?'disabled':''}>${setting?'Set PIN':'Unlock'}</button></div></form>`);
    $('#pin-cancel').onclick=()=>{close();$('#portal-select').value='child';};
    $('#pin-form').onsubmit=async e=>{e.preventDefault();if(Date.now()<data.lockUntil){pinDialog();return;}const f=new FormData(e.target), pin=f.get('pin');if(!/^\d{4}$/.test(pin)){pinDialog('Please enter exactly four digits.');return;}if(setting){if(pin!==f.get('confirm')){pinDialog('The PINs do not match. Please try again.');return;} const salt=Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join(''); data.pin={salt,hash:await digest(pin,salt)};data.attempts=0;} else if(await digest(pin,data.pin.salt)!==data.pin.hash){attemptFailure(data,Date.now());persist();pinDialog('That PIN did not match. Please try again.');return;}data.lockUntil=0;data.attempts=0;persist();unlocked=true;close();render();};
  }
  function switchPortal(){if($('#portal-select').value==='parent'){if(!unlocked){if(!crypto.subtle){$('#portal-select').value='child';alert('PIN setup requires a secure context such as localhost or HTTPS.');return;}pinDialog();return;}} else {unlocked=false;demo=false;}render();}
  $('#portal-select').onchange=switchPortal;
  $('#modal').addEventListener('close',()=>{if(!unlocked)$('#portal-select').value='child';});
  const disclaimer='<p class="routine-note">Routine support only—not medical advice or emergency monitoring. A missing check-in does not prove insulin was missed. Follow the child’s care plan; this app never recommends another dose.</p>';
  function rows(day, parent) {const meals=mealsFor(current(),day).sort((a,b)=>a.version.time.localeCompare(b.version.time));if(!meals.length)return '<p>No meals scheduled for today. A parent can add them in reminder settings.</p>';return meals.map(m=>{const r=recordFor(m,day), s=status(r,m,day,Date.now());return `<article class="routine-row ${r.helpAt&&!r.ackAt?'needs-help':''}"><div><strong>${esc(m.version.name)}</strong> <span class="routine-badge">${esc(s)}</span><p>Meal ${timeLabel(m.version.time)} · Reminder ${timeLabel(m.version.reminder)}${r.completedAt?' · Recorded '+fmt(r.completedAt):''}${r.helpAt?' · Help requested '+fmt(r.helpAt)+(r.ackAt?' · Acknowledged '+fmt(r.ackAt):''):''}${r.snoozeUntil&&r.snoozeUntil>Date.now()?' · Remind again '+fmt(r.snoozeUntil):''}</p></div><div class="routine-actions">${parent?`${r.helpAt&&!r.ackAt?`<button class="primary" data-action="ack" data-id="${esc(m.id)}">Acknowledge help</button>`:''}${!r.completedAt?`<button class="secondary" data-action="parent-record" data-id="${esc(m.id)}">Record for child</button>`:''}<button class="secondary" data-action="log" data-id="${esc(m.id)}">${r.log?'Edit meal log':'Meal log'}</button>`:`${!r.completedAt?`<button class="primary" data-action="child-record" data-id="${esc(m.id)}">I recorded my bolus</button><button class="secondary" data-action="snooze" data-id="${esc(m.id)}">Remind me in 5 minutes</button><button class="secondary" data-action="help" data-id="${esc(m.id)}">I need help</button>`:''}<button class="secondary" data-action="log" data-id="${esc(m.id)}">${r.log?'Edit meal log':'Meal log'}</button>`}</div>${r.log?`<p class="routine-log">${logText(r.log)}</p>`:''}</article>`;}).join('');}
  function logText(l){let text=`Meal log · ${esc(l.source)} · ${l.carbs!==''?esc(l.carbs)+' g estimated carbs · ':''}${l.bolus?'Reported bolus '+esc(l.bolus)+' · ':''}${l.mealStart?'Meal start '+esc(l.mealStart)+' · ':''}${l.note?esc(l.note):''}`;if(l.bolus&&l.mealStart){const minutes=(at('2000-01-01',l.mealStart)-at('2000-01-01',l.bolus))/60000;text+=` · Meal start ${Math.abs(minutes)} min ${minutes<0?'before':'after'} reported bolus (same day)`;}return text;}
  function render(){const parent=unlocked&&$('#portal-select').value==='parent';$('#routine-child').hidden=parent;$('#routine-parent').hidden=!parent;$('#content').hidden=parent;const day=dateKey(new Date());if(parent){const sums=summary(current()), totals=sums.reduce((a,x)=>({recorded:a.recorded+x.recorded,scheduled:a.scheduled+x.scheduled,help:a.help+x.help,snoozes:a.snoozes+x.snoozes}),{recorded:0,scheduled:0,help:0,snoozes:0});$('#routine-parent').innerHTML=`<div class="greeting"><div><div class="eyebrow">A LITTLE SUPPORT, TOGETHER</div><h1>Parent portal</h1><p>Keep the routine gentle, one check-in at a time.</p></div></div>${demo?'<div class="routine-demo">FICTIONAL DEMO DATA · Separate from your records</div>':''}<div class="routine-grid"><section class="card card-pad"><h2>Today’s meal check-ins</h2><p>Bolus check-ins recorded are self-reports, not verified insulin doses.</p>${rows(day,true)}</section><section class="card card-pad"><h2>Seven-day routine</h2><p><strong>${totals.recorded} of ${totals.scheduled}</strong> scheduled bolus check-ins recorded · ${totals.help} help requests · ${totals.snoozes} snoozes</p><div class="routine-trend">${sums.map(x=>`<div><strong>${new Date(x.day+'T12:00:00').toLocaleDateString([],{weekday:'short'})}</strong><span>${x.recorded}/${x.scheduled} recorded</span><small>${x.pending} pending · ${x.noRecord} past without record<br>${x.help} help · ${x.snoozes} snoozes</small></div>`).join('')}</div><p>Pending means the scheduled meal time is still ahead. Past without a record is not proof of a missed bolus.</p></section><section class="card card-pad"><h2>Meal reminder settings</h2><p>Set meal and reminder times according to your child’s existing care plan. No universal interval is assumed.</p>${current().meals.map(m=>{let v=m.versions[m.versions.length-1];return v.deleted?'':`<div class="routine-row"><strong>${esc(v.name)}</strong><p>Meal ${timeLabel(v.time)} · Reminder ${timeLabel(v.reminder)} · ${v.days.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', ')}</p><button class="secondary" data-action="edit" data-id="${esc(m.id)}">Edit</button> <button class="secondary" data-action="remove" data-id="${esc(m.id)}">Remove</button></div>`}).join('')}<button class="primary" data-action="add">Add meal</button></section><section class="card card-pad"><h2>Demo &amp; privacy</h2><p>Reminders appear in this app only while this page is open. Parent and child share data only in this browser; separate devices do not sync and no caregiver alert is sent. Browser data can be cleared.</p><div class="routine-actions"><button class="secondary" data-action="demo">${demo?'Exit fictional demo':'Use fictional demo data'}</button><button class="secondary" data-action="demo-reminder">Trigger demo reminder</button><button class="secondary" data-action="demo-help">Demonstrate help request</button></div>${disclaimer}</section></div>`;}else{$('#routine-child').innerHTML=`<section class="card card-pad routine-child-card"><div class="eyebrow">A LITTLE CHECK-IN</div><h2>Meal check-ins</h2><p>When it’s time, choose what you need. Asking for help is always okay.</p>${rows(day,false)}<p class="routine-note">Your check-ins stay in this browser. No message or alert is sent to a caregiver—please tell a trusted adult directly when you need help.</p></section>`;}if(reminderNotice){let el=document.createElement('div');el.className='routine-alert';el.setAttribute('role','status');el.innerHTML=`<span>${esc(reminderNotice)}</span><button class="secondary" data-action="dismiss">Dismiss</button>`; (parent?$('#routine-parent'):$('#routine-child')).prepend(el);}}
  function mealForm(meal){const v=meal?.versions.at(-1)||{name:'',time:'',reminder:'',days:[0,1,2,3,4,5,6]};dialog(`<div class="eyebrow">PARENT-CONFIGURED ROUTINE</div><h2>${meal?'Edit':'Add'} meal</h2><p>Use times from the child’s existing care plan. Changes apply from today onward.</p><form id="meal-form" class="routine-form"><label>Meal name<input name="name" maxlength="40" required value="${esc(v.name)}"></label><label>Meal time<input name="time" type="time" required value="${esc(v.time)}"></label><label>Reminder time<input name="reminder" type="time" required value="${esc(v.reminder)}"></label><fieldset><legend>Enabled days</legend><div class="routine-days">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${v.days.includes(i)?'checked':''}> ${d}</label>`).join('')}</div></fieldset><p class="routine-error" role="alert" id="meal-error"></p><div class="routine-actions"><button type="button" class="secondary" id="meal-cancel">Cancel</button><button class="primary">Save meal</button></div></form>`);$('#meal-cancel').onclick=close;$('#meal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target), days=f.getAll('days').map(Number), name=f.get('name').trim();if(!name||!days.length){$('#meal-error').textContent='Enter a meal name and select at least one day.';return;}const version={from:dateKey(new Date()),name,time:f.get('time'),reminder:f.get('reminder'),days};if(meal){if(meal.versions.at(-1).from===version.from)meal.versions.pop();meal.versions.push(version);}else current().meals.push({id:id(),versions:[version]});persist();close();render();};}
  function confirmRecord(m, source){dialog(`<div class="eyebrow">A LITTLE CHECK-IN</div><h2>Record a bolus check-in?</h2><p>This logs a bolus already taken according to the care plan. The app does not deliver or verify insulin.</p><div class="routine-actions"><button class="secondary" id="record-cancel">Not now</button><button class="primary" id="record-confirm">Record check-in</button></div>`);$('#record-cancel').onclick=close;$('#record-confirm').onclick=()=>{const day=dateKey(new Date());if(!recordFor(m,day).completedAt)put(m,day,actionRecord(recordFor(m,day),'record',Date.now(),source));close();render();};}
  function logForm(m){const day=dateKey(new Date()),l=recordFor(m,day).log||{carbs:'',bolus:'',mealStart:'',note:''};dialog(`<div class="eyebrow">OPTIONAL MEAL LOG</div><h2>${esc(m.version.name)} notes</h2><p>Estimates and reported times are personal notes, not a judgment of medical correctness. Times are compared on the same day.</p><form id="log-form" class="routine-form"><label>Estimated carbs (g)<input type="number" min="0" max="9999" step="0.1" name="carbs" value="${esc(l.carbs)}"></label><label>Reported bolus time<input type="time" name="bolus" value="${esc(l.bolus)}"></label><label>Actual meal-start time<input type="time" name="mealStart" value="${esc(l.mealStart)}"></label><label>Short note<input name="note" maxlength="160" value="${esc(l.note)}"></label><div class="routine-actions"><button type="button" class="secondary" id="log-cancel">Cancel</button><button class="primary">Save notes</button></div></form>`);$('#log-cancel').onclick=close;$('#log-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);put(m,day,{log:{carbs:f.get('carbs'),bolus:f.get('bolus'),mealStart:f.get('mealStart'),note:f.get('note').trim(),source:unlocked?'parent':'child'}});close();render();};}
  function makeDemo(){const day=dateKey(new Date()),now=new Date(),time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;demoData=blank();demoData.meals=[{id:'fictional-meal',versions:[{from:day,name:'Demo lunch',time,reminder:time,days:[0,1,2,3,4,5,6]}]}];}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!b.closest('#routine-parent, #routine-child'))return;const action=b.dataset.action, day=dateKey(new Date()), m=mealsFor(current(),day).find(x=>x.id===b.dataset.id)||current().meals.find(x=>x.id===b.dataset.id);if(action==='dismiss'){reminderNotice='';render();}else if(action==='add'&&unlocked)mealForm();else if(action==='edit'&&unlocked&&m)mealForm(m);else if(action==='remove'&&unlocked&&m){if(confirm('Remove this meal from today onward? Earlier records remain.')){const v={...m.versions.at(-1),from:day,deleted:true};if(m.versions.at(-1).from===day)m.versions.pop();m.versions.push(v);persist();render();}}else if(action==='child-record'&&m)confirmRecord(m,'child');else if(action==='parent-record'&&unlocked&&m)confirmRecord(m,'parent');else if(action==='snooze'&&m){const r=recordFor(m,day);if(!r.completedAt)put(m,day,actionRecord(r,'snooze',Date.now()));reminderNotice='';render();}else if(action==='help'&&m){const r=recordFor(m,day);if(!r.completedAt&&!r.helpAt)put(m,day,actionRecord(r,'help',Date.now()));reminderNotice='Please tell a trusted adult directly; this app does not send an alert.';render();}else if(action==='ack'&&unlocked&&m){put(m,day,actionRecord(recordFor(m,day),'ack',Date.now()));render();}else if(action==='log'&&m)logForm(m);else if(action==='demo'&&unlocked){demo=!demo;if(demo)makeDemo();reminderNotice='';render();}else if(action==='demo-reminder'&&unlocked){reminderNotice='DEMO reminder: It’s time for a fictional meal check-in. This stays in the app.';render();}else if(action==='demo-help'&&unlocked){if(!demo){demo=true;makeDemo();}const meal=demoData.meals[0];put(meal,day,{helpAt:Date.now(),ackAt:null});reminderNotice='DEMO: A fictional child requested help. No alert was sent.';render();}});
  function checkReminders(){const day=dateKey(new Date()),now=Date.now();for(const m of mealsFor(current(),day)){const r=recordFor(m,day);if(r.completedAt)continue;const due=r.snoozeUntil||at(day,m.version.reminder), marker=`${demo?'demo':'real'}|${m.id}|${day}|${due}`;if(now>=due&&!shown.has(marker)){shown.add(marker);reminderNotice=`${demo?'DEMO · ':''}${m.version.name}: time for a meal check-in. The app is open; no caregiver alert was sent.`;render();break;}}}
  render();checkReminders();setInterval(checkReminders,15000);
})(typeof window === 'undefined' ? globalThis : window);
